<?php defined( 'ABSPATH' ) || exit; $show = 'invoice' === $type ? LHIWC_Settings::get( 'show_logo' ) : LHIWC_Settings::get( 'packing_logo' ); ?>
<header class="lhiwc-header"><div class="lhiwc-brand"><?php if ( 'yes' === $show && $document['logo'] ) : ?><img src="<?php echo esc_url( $document['logo'] ); ?>" alt="<?php echo esc_attr( $document['store']['name'] ); ?>"><?php else : ?><h1><?php echo esc_html( $document['store']['name'] ); ?></h1><?php endif; ?></div><address><?php foreach ( array( 'address_1', 'address_2', 'city', 'state', 'postcode', 'country', 'phone', 'email' ) as $key ) { if ( $document['store'][ $key ] ) { echo esc_html( $document['store'][ $key ] ) . '<br>'; } } ?><?php if ( LHIWC_Settings::get( 'tax_number' ) ) : ?><strong><?php esc_html_e( 'Tax/GST:', 'lightweight-html-invoices-for-woocommerce' ); ?></strong> <?php echo esc_html( LHIWC_Settings::get( 'tax_number' ) ); ?><br><?php endif; ?><?php if ( LHIWC_Settings::get( 'company_number' ) ) : ?><strong><?php esc_html_e( 'Company:', 'lightweight-html-invoices-for-woocommerce' ); ?></strong> <?php echo esc_html( LHIWC_Settings::get( 'company_number' ) ); ?><?php endif; ?></address></header>

